// These tools are intercepted to return a "pending" result instead of executing
export function toClientToolDefinitions(
  tools: ClientToolDefinition[],
  onClientToolCall?: (toolName: string, params: Record<string, unknown>) => void,
  hookContext?: HookContext,
  reservedToolNames?: Set<string>,
): ToolDefinition[] {
  return tools.map((tool) => {
    const func = tool.function;
    // Security fix: prevent client tools from shadowing built-in tools
    // If a client tool name conflicts with a reserved (built-in) tool name,
    // automatically rename it with a "caller_" prefix.
    const originalName = func.name;
    const resolvedName =
      reservedToolNames && reservedToolNames.has(originalName)
        ? `caller_${originalName}`
        : originalName;
    return {
      name: resolvedName,
      label: resolvedName,
      description: func.description ?? "",
      parameters: func.parameters as ToolDefinition["parameters"],
      execute: async (...args: ToolExecuteArgs): Promise<AgentToolResult<unknown>> => {
        const { toolCallId, params } = splitToolExecuteArgs(args);
        const outcome = await runBeforeToolCallHook({
          toolName: resolvedName,
          params,
          toolCallId,
          ctx: hookContext,
        });
        if (outcome.blocked) {
          throw new Error(outcome.reason);
        }
        const adjustedParams = outcome.params;
        const paramsRecord = isPlainObject(adjustedParams) ? adjustedParams : {};
        // Notify handler that a client tool was called
        if (onClientToolCall) {
          onClientToolCall(originalName, paramsRecord);
        }
        // Return a pending result - the client will execute this tool
        return jsonResult({
          status: "pending",
          tool: originalName,
          message: "Tool execution delegated to client",
        });
      },
    } satisfies ToolDefinition;
  });
}

