// Simple test to verify the tool shadowing fix logic
// This tests the renaming logic without running the full application

const reservedToolNames = new Set(['read', 'write', 'exec', 'message', 'browser', 'canvas']);

function simulateToClientToolDefinitions(clientTools, reservedToolNames) {
  return clientTools.map((tool) => {
    const originalName = tool.name;
    const resolvedName =
      reservedToolNames && reservedToolNames.has(originalName)
        ? `caller_${originalName}`
        : originalName;

    return {
      ...tool,
      resolvedName,
      originalName,
    };
  });
}

// Test cases
const testCases = [
  {
    name: 'Tool name conflicts with built-in (read)',
    clientTools: [{ name: 'read', description: 'Read file' }],
    expected: [{ name: 'read', description: 'Read file', resolvedName: 'caller_read', originalName: 'read' }],
  },
  {
    name: 'Tool name conflicts with built-in (exec)',
    clientTools: [{ name: 'exec', description: 'Execute command' }],
    expected: [{ name: 'exec', description: 'Execute command', resolvedName: 'caller_exec', originalName: 'exec' }],
  },
  {
    name: 'Tool name does not conflict',
    clientTools: [{ name: 'my_custom_tool', description: 'Custom tool' }],
    expected: [{ name: 'my_custom_tool', description: 'Custom tool', resolvedName: 'my_custom_tool', originalName: 'my_custom_tool' }],
  },
  {
    name: 'Multiple tools with mixed conflicts',
    clientTools: [
      { name: 'write', description: 'Write file' },
      { name: 'my_tool', description: 'My tool' },
      { name: 'canvas', description: 'Canvas' },
    ],
    expected: [
      { name: 'write', description: 'Write file', resolvedName: 'caller_write', originalName: 'write' },
      { name: 'my_tool', description: 'My tool', resolvedName: 'my_tool', originalName: 'my_tool' },
      { name: 'canvas', description: 'Canvas', resolvedName: 'caller_canvas', originalName: 'canvas' },
    ],
  },
];

let allPassed = true;

testCases.forEach((testCase, index) => {
  console.log(`\n=== Test Case ${index + 1}: ${testCase.name} ===`);

  const result = simulateToClientToolDefinitions(testCase.clientTools, reservedToolNames);

  const passed = JSON.stringify(result) === JSON.stringify(testCase.expected);

  if (passed) {
    console.log('✅ PASSED');
    console.log('Input:', JSON.stringify(testCase.clientTools, null, 2));
    console.log('Output:', JSON.stringify(result, null, 2));
  } else {
    console.log('❌ FAILED');
    console.log('Input:', JSON.stringify(testCase.clientTools, null, 2));
    console.log('Expected:', JSON.stringify(testCase.expected, null, 2));
    console.log('Got:', JSON.stringify(result, null, 2));
    allPassed = false;
  }
});

console.log('\n=== Summary ===');
if (allPassed) {
  console.log('✅ All tests PASSED');
  process.exit(0);
} else {
  console.log('❌ Some tests FAILED');
  process.exit(1);
}
